package com.skillpilot.backend.identity;
import java.util.*;
import java.lang.reflect.*;
import com.skillpilot.backend.completion.CompletionCanonicalGraphResolver;
import com.skillpilot.backend.landscape.LearningGoal;
public class OwnerNamespaceReview {
 static String OWNER="ab000000-0000-4000-8000-000000000001", UPPER=OWNER.toUpperCase(Locale.ROOT);
 static String G="bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb", H="cccccccc-cccc-4ccc-8ccc-cccccccccccc";
 static void check(String name,boolean result){ if(!result)throw new AssertionError(name);System.out.println(name+"=true"); }
 static Object field(Object x,String n)throws Exception {Field f=x.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(x);}
 static Object call(Object x,String n)throws Exception {Method m=x.getClass().getDeclaredMethod(n);m.setAccessible(true);return m.invoke(x);}
 public static void main(String[] args)throws Exception {
  var map=new GoalIdentityMap(List.of(),Map.of(G,Set.of(OWNER),H,Set.of(UPPER)),Set.of(G,H));
  check("JAVA_ACCEPTS_WRONG_CASE_DISTINCT_OWNER",G.equals(map.canonicalGoalId(UPPER+":"+G)));
  check("JAVA_ACCEPTS_REVERSE_WRONG_OWNER",H.equals(map.canonicalGoalId(OWNER+":"+H)));
  check("JAVA_EXACT_OWNER_UPPER_GOAL_CONTROL",G.equals(map.canonicalGoalId(OWNER+":"+G.toUpperCase(Locale.ROOT))));
  var opaque=new GoalIdentityMap(List.of(),Map.of(G,Set.of("canonical-math-de")),Set.of(G));
  boolean rejects=false;try {opaque.canonicalGoalId("CANONICAL-MATH-DE:"+G);}catch(GoalIdentityException e){rejects=true;}
  check("JAVA_OPAQUE_OWNER_CASE_REJECTED_CONTROL",rejects);
  var resolver=new CompletionCanonicalGraphResolver(null,null);
  Method resolve=CompletionCanonicalGraphResolver.class.getDeclaredMethod("resolve",String.class,Map.class,Map.class);resolve.setAccessible(true);
  var goals=Map.of(G,new LearningGoal(),H,new LearningGoal());var owners=Map.of(G,Set.of(OWNER),H,Set.of(UPPER));
  check("PRODUCTIVE_RESOLVER_WRONG_OWNER_UNRESOLVED",(UPPER+":"+G).equals(resolve.invoke(resolver,UPPER+":"+G,goals,owners)));
  check("PRODUCTIVE_RESOLVER_EXACT_OWNER_RESOLVED",G.equals(resolve.invoke(resolver,OWNER+":"+G,goals,owners)));
  check("PRODUCTIVE_RESOLVER_UPPER_GOAL_SEPARATELY_UNRESOLVED",(OWNER+":"+G.toUpperCase(Locale.ROOT)).equals(resolve.invoke(resolver,OWNER+":"+G.toUpperCase(Locale.ROOT),goals,owners)));
  var constructor=Class.forName("com.skillpilot.backend.identity.GoalIdentityServiceTest$Fixture").getDeclaredConstructor();constructor.setAccessible(true);Object f=constructor.newInstance();
  var proof=new SourceIdentityProofVerifier().verify((byte[])call(f,"manifestBytes"),(SourceIdentityProofVerifier.AcceptedBinding)call(f,"binding"),(SourceIdentityProofVerifier.SnapshotInputs)f);
  String unchanged=(String)((List<?>)field(f,"unchangedIds")).getFirst();
  check("VERIFIED_A_ACCEPTS_UNREGISTERED_UPPER_OWNER",OWNER.equals(proof.originalReviewDefinition(UPPER,unchanged).landscapeId()));
  String old=(String)((List<?>)field(f,"oldIds")).getFirst(), target=(String)((List<?>)field(f,"targets")).getFirst();
  check("VERIFIED_A_RENAMED_ID_WRONG_OWNER_ACCEPTED",target.equals(proof.canonicalGoalIdForCandidateQa(UPPER+":"+old)));
  check("VERIFIED_A_GOAL_UUID_CASE_CONTROL",unchanged.equals(proof.originalReviewDefinition(OWNER,unchanged.toUpperCase(Locale.ROOT)).originalGoalId()));
 }
}
